-- 4a — EXPECTED: every rule on a workspace.* table.
SELECT target_table, status, COUNT(*) AS rules FROM workspace.dq_triage.dq_config_v_rule_registry_current
WHERE  cde_id LIKE 'KA\\_%' GROUP BY 1, 2 ORDER BY 1, 2;

-- 4b — EXPECTED: 22 bindings, all on workspace.*.
SELECT b.target_table, COUNT(*) AS attributes FROM workspace.dq_triage.dq_config_v_cde_registry_current c
LATERAL VIEW explode(c.bindings) x AS b
WHERE  c.cde_id LIKE 'KA\\_%' GROUP BY 1 ORDER BY 1;

